package com.example.mxb.manager;

import com.example.mxb.MxbPlugin;
import com.example.mxb.config.CheatType;
import com.example.mxb.data.Ban;
import com.example.mxb.util.TimeUtil;
import org.bukkit.entity.Player;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.logging.Level;

public class BanManager {

    private final MxbPlugin plugin;

        public BanManager(MxbPlugin plugin) {
                this.plugin = plugin;
                    }

                        public Ban getActiveBan(UUID uuid) {
                                try (PreparedStatement ps = plugin.getDatabase().getConnection().prepareStatement(
                                                "SELECT * FROM bans WHERE uuid = ? AND active = 1 ORDER BY id DESC LIMIT 1")) {
                                                            ps.setString(1, uuid.toString());
                                                                        try (ResultSet rs = ps.executeQuery()) {
                                                                                        if (rs.next()) {
                                                                                                            Ban b = map(rs);
                                                                                                                                if (b.getEndTime() > 0 && b.getEndTime() < System.currentTimeMillis()) {
                                                                                                                                                        deactivate(b.getId(), null, null, "SYSTEM_EXPIRE");
                                                                                                                                                                                return null;
                                                                                                                                                                                                    }
                                                                                                                                                                                                                        return b;
                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                            } catch (SQLException e) {
                                                                                                                                                                                                                                                                        plugin.getLogger().log(Level.SEVERE, "查询封禁失败", e);
                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                        return null;
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                public void ban(Player target, CheatType type, Player operator) {
                                                                                                                                                                                                                                                                                                        long now = System.currentTimeMillis();
                                                                                                                                                                                                                                                                                                                long end = type.getBanDuration() < 0 ? -1 : now + type.getBanDuration();

                                                                                                                                                                                                                                                                                                                        try (PreparedStatement ps = plugin.getDatabase().getConnection().prepareStatement(
                                                                                                                                                                                                                                                                                                                                        "INSERT INTO bans (uuid, name, ip, reason, cheat_type, cheat_type_name, " +
                                                                                                                                                                                                                                                                                                                                                        "start_time, end_time, operator_uuid, operator_name, active) " +
                                                                                                                                                                                                                                                                                                                                                                        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)")) {
                                                                                                                                                                                                                                                                                                                                                                                    ps.setString(1, target.getUniqueId().toString());
                                                                                                                                                                                                                                                                                                                                                                                                ps.setString(2, target.getName());
                                                                                                                                                                                                                                                                                                                                                                                                            ps.setString(3, target.getAddress() == null ? null : target.getAddress().getHostString());
                                                                                                                                                                                                                                                                                                                                                                                                                        ps.setString(4, type.getReason());
                                                                                                                                                                                                                                                                                                                                                                                                                                    ps.setString(5, type.getId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                ps.setString(6, type.getName());
                                                                                                                                                                                                                                                                                                                                                                                                                                                            ps.setLong(7, now);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ps.setLong(8, end);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ps.setString(9, operator == null ? null : operator.getUniqueId().toString());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ps.setString(10, operator == null ? "控制台" : operator.getName());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ps.executeUpdate();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (SQLException e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                plugin.getLogger().log(Level.SEVERE, "写入封禁失败", e);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                target.kickPlayer(buildScreen(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                plugin.getConfig().getStringList("kick-screen"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                target.getName(), type.getReason(), type.getName(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                operator == null ? "控制台" : operator.getName(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        public String buildScreen(List<String> lines, String playerName, String reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      String cheatName, String operator, long endTime) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              String remaining = endTime < 0 ? "永久"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : TimeUtil.formatDuration(TimeUtil.remaining(endTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      String expire = TimeUtil.formatDate(endTime);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              StringBuilder sb = new StringBuilder();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      for (int i = 0; i < lines.size(); i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  String line = lines.get(i)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .replace("%player%", nvl(playerName))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .replace("%reason%", nvl(reason))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .replace("%cheat_type%", nvl(cheatName))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .replace("%remaining%", remaining)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .replace("%expire%", expire)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .replace("%operator%", nvl(operator));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      sb.append(TimeUtil.color(line));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (i < lines.size() - 1) sb.append("\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return sb.toString();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          public boolean unban(UUID uuid, Player operator) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  try (PreparedStatement ps = plugin.getDatabase().getConnection().prepareStatement(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "UPDATE bans SET active = 0, unbanned_by_uuid = ?, unbanned_by_name = ?, " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "unban_time = ?, unban_reason = 'MANUAL' WHERE uuid = ? AND active = 1")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ps.setString(1, operator == null ? null : operator.getUniqueId().toString());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ps.setString(2, operator == null ? "控制台" : operator.getName());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ps.setLong(3, System.currentTimeMillis());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ps.setString(4, uuid.toString());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return ps.executeUpdate() > 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (SQLException e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  plugin.getLogger().log(Level.SEVERE, "解封失败", e);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          public void deactivate(int banId, String byUuid, String byName, String reason) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  try (PreparedStatement ps = plugin.getDatabase().getConnection().prepareStatement(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "UPDATE bans SET active = 0, unbanned_by_uuid = ?, unbanned_by_name = ?, " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "unban_time = ?, unban_reason = ? WHERE id = ?")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ps.setString(1, byUuid);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ps.setString(2, byName);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ps.setLong(3, System.currentTimeMillis());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ps.setString(4, reason);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ps.setInt(5, banId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ps.executeUpdate();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch (SQLException e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              e.printStackTrace();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              public List<Ban> getHistory(UUID uuid) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      List<Ban> list = new ArrayList<>();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try (PreparedStatement ps = plugin.getDatabase().getConnection().prepareStatement(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "SELECT * FROM bans WHERE uuid = ? ORDER BY id DESC")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ps.setString(1, uuid.toString());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      try (ResultSet rs = ps.executeQuery()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      while (rs.next()) list.add(map(rs));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch (SQLException e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      e.printStackTrace();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return list;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              private Ban map(ResultSet rs) throws SQLException {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Ban b = new Ban();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setId(rs.getInt("id"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setUuid(rs.getString("uuid"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setName(rs.getString("name"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setIp(rs.getString("ip"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setReason(rs.getString("reason"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setCheatType(rs.getString("cheat_type"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setCheatTypeName(rs.getString("cheat_type_name"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setStartTime(rs.getLong("start_time"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setEndTime(rs.getLong("end_time"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setOperatorUuid(rs.getString("operator_uuid"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setOperatorName(rs.getString("operator_name"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setActive(rs.getInt("active") == 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setUnbannedByUuid(rs.getString("unbanned_by_uuid"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setUnbannedByName(rs.getString("unbanned_by_name"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              b.setUnbanTime(rs.getLong("unban_time"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      b.setUnbanReason(rs.getString("unban_reason"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return b;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      private static String nvl(String s) { return s == null ? "" : s; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }